"""Run Forge-generated byte indexing in fresh warmed Node processes on one Linux CPU."""
import argparse
import datetime
import json
import os
from pathlib import Path
import platform
import re
import shutil
import statistics
import subprocess
import tempfile

from function_lookup_bench import digest


HERE = Path(__file__).resolve().parent
SOURCE = HERE / "js_byte_index.fg"
BRIDGE = HERE / "js_byte_index.cjs"


def cases():
    valid = "0123456789abcdef" * 4
    for name, value in [
        ("valid", valid), ("late_bad", valid[:-1] + "g"), ("early_bad", "Z" + valid[1:]),
        ("short", valid[:-1]), ("unicode_64_bytes", valid[:-2] + "é"),
        ("unicode_65_bytes", valid[:-1] + "é"),
    ]:
        count = {"early_bad": 60000, "short": 180000, "unicode_65_bytes": 180000,
                 "valid": 4000}.get(name, 3000)
        yield "digest_" + name, "digest", [value], 0, count

    large = "a界😀" * 512  # 4096 UTF-8 bytes
    for operation in ("chars", "brackets"):
        for name, value, count in [("ascii", valid, 2400), ("unicode", "aé界😀\0z" * 4, 2400),
                                   ("4k", large, 8)]:
            yield f"{operation}_{name}", operation, [value], 0, count
    yield "views_4k", "views", [large], 0, 160
    huge = "a" * 131070 + "é"
    for offset in (0, 130):
        yield f"at_128k_{offset}", "at", [huge], offset, 900
    yield "at_4k_late", "at", [large], 3763, 12000
    for name, width, offset, count in [
        ("short", 24, 12, 24000), ("4k_front", 4096, 2, 4000),
        ("4k_middle", 4096, 130, 4000), ("4k_late", 4096, 3763, 4000),
    ]:
        # Each timed and warmup call receives a different, already parsed string.
        inputs = [f"{i:08x}" + (chr(65 + i % 26) * (width - 9)) + "é"
                  for i in range(count + 2 * (count // 4))]
        yield f"distinct_{name}", "at", inputs, offset, count
    count = 4000
    similar = ["p" * 3756 + f"{i:08x}" + "é" * 166 for i in range(count + 2 * (count // 4))]
    yield "distinct_4k_common_prefix_late", "at", similar, 3763, count
    yield "loop_distinct_4k_common_prefix_late", "stream", similar, 3763, count
    yield "loop_alternating_4k_common_prefix_late", "stream", similar[:2], 3763, 12000
    yield "loop_repeated_4k_late", "stream", [large], 3763, 12000
    yield "loop_over_limit_late", "stream", ["a" * 65536 + "é"], 65000, 1200


def oracle(operation, inputs, offset, count):
    def value(s):
        data = s.encode("utf-8")
        if operation in ("at", "stream"):
            return data[offset]
        if operation == "digest":
            return int(re.fullmatch(b"[0-9a-f]{64}", data) is not None)
        if operation == "views":
            data = data.partition(b"\0")[0]
        return sum(data)

    start = 2 * max(1, count // 4)
    return str(sum(value(inputs[(start + i) % len(inputs)]) for i in range(count)))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("baseline", "root", "output"):
        parser.add_argument("--" + name, type=Path, required=True)
    parser.add_argument("--candidate", type=Path, help="Omit to validate baseline once per input")
    parser.add_argument("--cpu", type=int, required=True)
    parser.add_argument("--pairs", type=int, default=8)
    parser.add_argument("--case", action="append", help="Restrict to named workloads")
    parser.add_argument("--build-note", required=True)
    args = parser.parse_args()
    if args.candidate and args.pairs < 2:
        parser.error("need at least two alternating pairs")
    os.sched_setaffinity(0, {args.cpu})
    node = Path(shutil.which("node")).resolve()
    compilers = {"baseline": args.baseline.resolve()}
    if args.candidate:
        compilers["candidate"] = args.candidate.resolve()
    report = dict(started_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  method="Fresh Node per sample, preparse strings, warm twice at 1/4 count, "
                         "time callback loop with hrtime.bigint, verify checksum in Python. "
                         "Alternate AB/BA by pair, stagger first order by case.",
                  platform=platform.platform(), cpu=args.cpu,
                  cpu_model=next(line.split(':', 1)[1].strip()
                                 for line in Path("/proc/cpuinfo").read_text().splitlines()
                                 if line.startswith("model name")),
                  node=subprocess.check_output([node, "--version"], text=True).strip(),
                  node_sha256=digest(node), build_note=args.build_note,
                  compiler_sha256={k: digest(v) for k, v in compilers.items()},
                  input_sha256={p.name: digest(p) for p in (SOURCE, BRIDGE, Path(__file__))},
                  cases={})
    with tempfile.TemporaryDirectory() as tmp:
        work = Path(tmp)
        emitted = {label: work / (label + ".js") for label in compilers}
        for label, compiler in compilers.items():
            subprocess.run([compiler, SOURCE, "--emit-js", "--forge-root", args.root.resolve(),
                            "-o", emitted[label]], check=True)
        report["emitted_js_sha256"] = {k: digest(v) for k, v in emitted.items()}
        config_file = work / "input.json"
        for index, (name, op, inputs, offset, count) in enumerate(cases()):
            if args.case and name not in args.case:
                continue
            config_file.write_text(json.dumps(dict(operation=op, inputs=inputs, offset=offset, count=count)))
            expected = oracle(op, inputs, offset, count)
            samples = []
            for n in range(args.pairs if args.candidate else 1):
                order = list(compilers) if (n + index) % 2 == 0 else list(reversed(compilers))
                observed = {}
                for label in order:
                    run = subprocess.run([node, "--require", BRIDGE, emitted[label], config_file],
                                         capture_output=True, text=True, check=True, timeout=60)
                    result = json.loads(run.stdout)
                    if run.stderr or result["result"] != expected or result["ns"] <= 0:
                        raise ValueError(f"{name} {label}: {run.stderr} {result}, expected {expected}")
                    observed[label] = result
                samples.append(dict(order=order, values=observed))
            row = dict(operation=op, count=count, input_count=len(inputs), offset=offset,
                       config_sha256=digest(config_file), expected=expected, samples=samples)
            row["median_ms"] = {k: statistics.median(s["values"][k]["ns"] for s in samples) / 1e6
                                for k in compilers}
            if args.candidate:
                changes = [100 * (s["values"]["candidate"]["ns"] / s["values"]["baseline"]["ns"] - 1)
                           for s in samples]
                q1, _, q3 = statistics.quantiles(changes, method="inclusive")
                row["paired_change_pct"] = dict(median=statistics.median(changes), q1=q1, q3=q3,
                                                min=min(changes), max=max(changes))
            print(name, row["median_ms"], row.get("paired_change_pct", {}), flush=True)
            report["cases"][name] = row
        if args.case and set(args.case) - report["cases"].keys():
            parser.error("unknown case name")
    args.output.write_text(json.dumps(report, indent=2) + "\n")


if __name__ == "__main__":
    main()
